// Synthetic-data forecasts are generated by the same validated Python pipeline used by the API.
import { createHash } from "node:crypto";
import dotenv from "dotenv";
import mongoose from "mongoose";
import MarketPrice from "../models/MarketPrice.js";
import MarketPriceForecast from "../models/MarketPriceForecast.js";
import Product from "../models/Product.js";
import User from "../models/User.js";
import Workspace from "../models/Workspace.js";
import {
  buildPriceForecastSummary,
  runPriceForecast,
} from "../services/marketPriceForecast.js";

const horizons = [7, 30, 60];
const stableHash = (value) =>
  createHash("sha256")
    .update(JSON.stringify(value))
    .digest("hex")
    .slice(0, 20)
    .toUpperCase();

const parseArgs = (args) => {
  const parsed = {};
  for (let index = 0; index < args.length; index += 1) {
    const option = args[index];
    if (option === "--help" || option === "-h") {
      parsed.help = true;
      continue;
    }
    if (option === "--apply") {
      parsed.apply = true;
      continue;
    }
    if (
      ![
        "--database",
        "--workspace-id",
        "--member-id",
        "--dataset-id",
        "--confirm-plan",
      ].includes(option)
    ) {
      throw new Error(`Unknown option: ${option}`);
    }
    const value = args[index + 1];
    if (!value || value.startsWith("--"))
      throw new Error(`A value is required after ${option}`);
    parsed[option.slice(2)] = value;
    index += 1;
  }
  if (!parsed.help) {
    for (const required of ["database", "workspace-id", "member-id"]) {
      if (!parsed[required]) throw new Error(`--${required} is required`);
    }
    if (Boolean(parsed.apply) !== Boolean(parsed["confirm-plan"])) {
      throw new Error("--apply and --confirm-plan must be provided together");
    }
  }
  return parsed;
};

const assertLocalDatabaseTarget = (databaseName) => {
  if (!process.env.MONGODB_URI)
    throw new Error(
      "MONGODB_URI is not set. No database connection was attempted.",
    );
  let uri;
  try {
    uri = new URL(process.env.MONGODB_URI);
  } catch {
    throw new Error("MONGODB_URI is invalid; its value is not displayed.");
  }
  const localHosts = new Set(["localhost", "127.0.0.1", "::1"]);
  if (
    uri.protocol !== "mongodb:" ||
    !localHosts.has(uri.hostname.replace(/^\[|\]$/g, ""))
  ) {
    throw new Error("Only an explicitly local mongodb:// URI is permitted.");
  }
  const connectedDatabase = decodeURIComponent(
    uri.pathname.replace(/^\/+/, ""),
  );
  if (connectedDatabase !== databaseName) {
    throw new Error(
      `The --database value must exactly match the database name in MONGODB_URI (expected ${connectedDatabase || "an explicit database name"}).`,
    );
  }
};

const showHelp = () => {
  console.log(
    [
      "Usage:",
      "  npm run sample-price-forecasts -- --database <local-db> --workspace-id <id> --member-id <id> [--dataset-id <id>]",
      "  npm run sample-price-forecasts -- --database <local-db> --workspace-id <id> --member-id <id> [--dataset-id <id>] --apply --confirm-plan <token>",
      "",
      "The first command runs a read-only preflight and the project Python forecast model.",
      "The second stores only forecasts for the identified synthetic market-price dataset in a transaction.",
    ].join("\n"),
  );
};

const loadTarget = async ({ workspaceId, memberId }) => {
  if (
    !mongoose.isValidObjectId(workspaceId) ||
    !mongoose.isValidObjectId(memberId)
  ) {
    throw new Error(
      "Workspace and member identifiers must be valid MongoDB ObjectIds.",
    );
  }
  const [workspace, member] = await Promise.all([
    Workspace.findOne({ _id: workspaceId, members: memberId })
      .select("_id name members")
      .lean(),
    User.findOne({ _id: memberId, isActive: true }).select("_id").lean(),
  ]);
  if (!workspace || !member)
    throw new Error(
      "The active member must already belong to the specified workspace.",
    );
  const creators = await User.find({
    _id: { $in: workspace.members },
    isActive: true,
    role: { $in: ["admin", "manager", "store_keeper"] },
  })
    .select("_id role")
    .lean();
  if (!creators.length)
    throw new Error(
      "No active admin, manager, or store-keeper workspace member is available as a forecast creator.",
    );
  return { workspace, creatorIds: creators.map(({ _id }) => _id) };
};

const createForecastPlan = async ({ workspaceId, datasetId, creatorIds }) => {
  const records = await MarketPrice.find({
    workspaceId,
    sampleDatasetId: datasetId,
    dataOrigin: "sample",
    priceType: "Retail",
    currency: "LKR",
  })
    .sort({ product: 1, recordedAt: 1, createdAt: 1 })
    .select("product price recordedAt")
    .lean();
  const grouped = new Map();
  for (const record of records) {
    const key = String(record.product);
    if (!grouped.has(key)) grouped.set(key, []);
    grouped
      .get(key)
      .push({ price: record.price, recordedAt: record.recordedAt });
  }
  const products = await Product.find({
    _id: { $in: [...grouped.keys()] },
    workspaceId,
    isActive: true,
  })
    .select("_id productName currentStock minimumStock costPrice")
    .lean();
  const productsById = new Map(
    products.map((product) => [String(product._id), product]),
  );
  const forecasts = [];
  for (const [productId, history] of grouped) {
    const product = productsById.get(productId);
    if (!product)
      throw new Error(
        `Synthetic market history references a missing or inactive workspace product (${productId}).`,
      );
    for (const horizon of horizons) {
      const result = await runPriceForecast(history, horizon);
      forecasts.push(
        buildPriceForecastSummary({
          workspaceId,
          product,
          currentPrice: history[history.length - 1].price,
          result,
          priceType: "Retail",
          forecastPeriod: horizon,
          generatedBy: creatorIds[forecasts.length % creatorIds.length],
          generatedAt: new Date(),
        }),
      );
    }
  }
  return forecasts;
};

const main = async () => {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) return showHelp();
  dotenv.config();
  assertLocalDatabaseTarget(args.database);
  await mongoose.connect(process.env.MONGODB_URI, {
    autoIndex: false,
    autoCreate: false,
    bufferCommands: false,
    serverSelectionTimeoutMS: 5000,
    maxPoolSize: 5,
  });
  try {
    const { workspace, creatorIds } = await loadTarget({
      workspaceId: args["workspace-id"],
      memberId: args["member-id"],
    });
    const datasetId = args["dataset-id"] || "ahs-yamaha-synthetic-v2";
    const hello = await mongoose.connection.db.admin().command({ hello: 1 });
    const transactionSupport = Boolean(
      hello.setName || hello.msg === "isdbgrid",
    );
    const planned = await createForecastPlan({
      workspaceId: args["workspace-id"],
      datasetId,
      creatorIds,
    });
    const keys = planned.map(
      (forecast) =>
        `${forecast.product}:${forecast.priceType}:${forecast.forecastPeriod}`,
    );
    const existing = await MarketPriceForecast.find({
      workspaceId: args["workspace-id"],
      sampleDatasetId: datasetId,
      dataOrigin: "sample",
    })
      .select("product priceType forecastPeriod")
      .lean();
    const existingKeys = existing.map(
      (forecast) =>
        `${forecast.product}:${forecast.priceType}:${forecast.forecastPeriod}`,
    );
    const expectedKeys = new Set(keys);
    const existingKeySet = new Set(existingKeys);
    const exactExistingSet =
      existingKeys.length === expectedKeys.size &&
      existingKeys.every((key) => expectedKeys.has(key)) &&
      expectedKeys.size === existingKeySet.size;
    const collisions = existingKeys.filter((key) => !expectedKeys.has(key));
    const missing = planned.filter(
      (forecast) =>
        !existingKeySet.has(
          `${forecast.product}:${forecast.priceType}:${forecast.forecastPeriod}`,
        ),
    );
    const reliable = planned.filter(
      (forecast) =>
        forecast.status === "reliable" &&
        Number.isFinite(forecast.predictedPrice) &&
        forecast.predictedPrice > 0,
    );
    const confirmation = stableHash({
      database: mongoose.connection.name,
      workspaceId: String(args["workspace-id"]),
      datasetId,
      expectedKeys: [...expectedKeys].sort(),
      predictions: planned.map(
        ({ product, forecastPeriod, status, predictedPrice }) => ({
          product: String(product),
          forecastPeriod,
          status,
          predictedPrice,
        }),
      ),
    });
    console.log("\nSYNTHETIC MARKET PRICE FORECAST PREFLIGHT");
    console.log(`Database: ${mongoose.connection.name}`);
    console.log(`Workspace: ${workspace.name} (${workspace._id})`);
    console.log(`Dataset ID: ${datasetId}`);
    console.log(
      `Products with synthetic Retail history: ${groupedProductCount(planned)}`,
    );
    console.log(
      `Transaction support: ${transactionSupport ? "replica set / sharded cluster detected" : "NOT DETECTED; apply is refused"}`,
    );
    console.log(
      `Forecasts planned: ${planned.length} (${horizons.join(", ")} day horizons)`,
    );
    console.log(`Reliable non-zero model predictions: ${reliable.length}`);
    console.log(`Existing matching forecast records: ${existing.length}`);
    console.log(`Forecast records to insert: ${missing.length}`);
    console.log(
      `Existing dataset state: ${existing.length === 0 ? "empty" : exactExistingSet ? "complete" : "partial or conflicting"}`,
    );
    console.log("No records were written during this preflight.");
    console.log(`Plan confirmation token: ${confirmation}`);
    if (!args.apply) return;
    if (!transactionSupport)
      throw new Error(
        "Apply requires a replica set or sharded MongoDB cluster. No records were written.",
      );
    if (collisions.length || (existing.length && !exactExistingSet)) {
      throw new Error(
        "Existing forecast records are partial or conflict with this dataset plan. No records were written.",
      );
    }
    if (reliable.length === 0)
      throw new Error(
        "The model produced no reliable, non-zero forecasts. No records were written.",
      );
    if (existing.length === expectedKeys.size && exactExistingSet) {
      console.log("\nNo-op: forecasts for this dataset already exist.");
      return;
    }
    if (confirmation !== args["confirm-plan"]) {
      throw new Error(
        "The confirmation token does not match the current forecast plan. No records were written.",
      );
    }
    await MarketPriceForecast.collection.createIndex(
      { workspaceId: 1, sampleDatasetId: 1, sampleRecordKey: 1 },
      {
        unique: true,
        partialFilterExpression: {
          sampleDatasetId: { $type: "string" },
          sampleRecordKey: { $type: "string" },
        },
      },
    );
    const session = await mongoose.startSession();
    try {
      await session.withTransaction(
        async () => {
          await MarketPriceForecast.insertMany(
            missing.map((forecast) => ({
              ...forecast,
              dataOrigin: "sample",
              sampleDatasetId: datasetId,
              sampleRecordKey: `${forecast.product}-${forecast.priceType}-${forecast.forecastPeriod}`,
            })),
            { session },
          );
        },
        {
          readConcern: { level: "snapshot" },
          writeConcern: { w: "majority" },
          readPreference: "primary",
          maxCommitTimeMS: 30000,
        },
      );
    } finally {
      await session.endSession();
    }
    console.log(
      `\nStored ${missing.length} validated model forecasts transactionally.`,
    );
  } finally {
    await mongoose.disconnect();
  }
};

const groupedProductCount = (forecasts) =>
  new Set(forecasts.map((forecast) => String(forecast.product))).size;

main().catch(async (error) => {
  console.error(`Synthetic price forecast generator failed: ${error.message}`);
  await mongoose.disconnect();
  process.exitCode = 1;
});
